import { defineEval } from "eve/evals";
import { loadYaml } from "eve/evals/loaders";

// Harness requirement: no untrusted judges. This eval replays 20 human-labeled
// examples against the pinned judge (evals/evals.config.ts) and requires
// >= 90% agreement. If it drifts, every judge-backed gate in this suite is
// untrusted until the judge is recalibrated. Labels live in
// evals/data/judge-calibration.yaml and are never generated by the judge.
//
// This eval drives no agent turns — it grades known text, so it is cheap and
// fully deterministic in structure.

type CalibrationExample = {
  id: string;
  criterion: string;
  reply: string;
  label: string;
  /** For "no" labels: the positive criterion the failing reply satisfies. */
  positive_failure?: string;
};

const calibration = (await loadYaml(
  "evals/data/judge-calibration.yaml",
)) as unknown as readonly CalibrationExample[];

export default calibration.map((example) =>
  defineEval({
    description: `Judge calibration ${example.id}: pinned judge must match the human label.`,
    tags: ["reliability", "calibration"],
    async test(t) {
      if (example.label === "yes") {
        t.judge.autoevals
          .closedQA(example.criterion, { on: example.reply })
          .atLeast(0.8);
      } else {
        // For a "no" label the reply fails the original criterion. The graded
        // check is the human-authored positive failure criterion (never a
        // double negative — those flip the judge).
        t.judge.autoevals
          .closedQA(
            example.positive_failure ??
              `The reply does NOT satisfy this: ${example.criterion}`,
            { on: example.reply },
          )
          .atLeast(0.8);
      }
    },
  }),
);
